/**
 * Offline risk engine: a line-for-line port of backend/app/ml. It runs on the phone with no
 * network, and shared/fixtures/risk_cases.json (generated by the Python engine) proves the two
 * produce identical output. Change both together, then regenerate the fixtures.
 */
import type {
  Band,
  CbacResult,
  ConditionKey,
  ConditionResult,
  Driver,
  RedFlag,
  RiskResult,
  ScreeningInput,
  Urgency,
} from "@/models/types/risk";
import { riskFor, termContributions, WHO_CVD } from "./whoCvd";
import { predict as modelPredict } from "./model";

export const ENGINE_VERSION = "0.2.0";
export const MIN_AGE = 30;

const BANDS: Band[] = ["low", "moderate", "high"];
const DIABETES_SYMPTOMS = ["excessive_thirst", "frequent_urination", "slow_healing_wounds", "blurred_vision", "tingling_numbness"];
const TB_CORE_SYMPTOMS = ["cough_2_weeks", "fever", "night_sweats", "weight_loss"];
const STROKE_SIGNS = ["face_droop", "arm_weakness", "speech_difficulty"];
const ALTERED_CONSCIOUSNESS = ["unconscious", "seizure", "confusion"];
const HTN_EMERGENCY_SYMPTOMS = ["chest_pain", "severe_headache", "confusion", "severe_breathlessness", "blurred_vision"];
const PREGNANCY_DANGER = [
  "pregnancy_bleeding",
  "pregnancy_severe_headache",
  "pregnancy_convulsions",
  "pregnancy_swelling",
  "reduced_fetal_movement",
];

type X = ScreeningInput & { symptoms: string[] };

// ------------------------------------------------------------------ helpers

const round = (x: number) => Math.floor(x + 0.5);
const clamp = (x: number, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, x));
const has = (v: unknown) => v !== undefined && v !== null;
const bandMax = (a: Band, b: Band): Band => (BANDS.indexOf(a) >= BANDS.indexOf(b) ? a : b);
const bump = (b: Band): Band => BANDS[Math.min(2, BANDS.indexOf(b) + 1)];

function driver(code: string, points: number, value?: string | number | null, direction: "up" | "down" = "up"): Driver {
  const d: Driver = { code, points, direction };
  if (value !== undefined && value !== null) d.value = value;
  return d;
}

function topDrivers(drivers: Driver[], n = 3): Driver[] {
  return [...drivers].sort((a, b) => Math.abs(b.points) - Math.abs(a.points)).filter((d) => d.points !== 0).slice(0, n);
}

function validReadings(x: X): [number, number][] {
  return (x.bp_readings ?? []).filter((r) => r && r[0] && r[1]);
}

export function bpSummary(x: X): [number | null, number | null, number | null, number | null] {
  const r = validReadings(x);
  if (!r.length) return [null, null, null, null];
  const n = r.length;
  return [
    round(r.reduce((s, v) => s + v[0], 0) / n),
    round(r.reduce((s, v) => s + v[1], 0) / n),
    Math.max(...r.map((v) => v[0])),
    Math.max(...r.map((v) => v[1])),
  ];
}

export function bmi(x: ScreeningInput): number | null {
  if (!x.height_cm || !x.weight_kg) return null;
  return Math.floor((x.weight_kg / (x.height_cm / 100) ** 2) * 10 + 0.5) / 10;
}

function glucoseStatus(x: X): "diabetic" | "borderline" | "normal" | "low" | null {
  const g = x.glucose_mg_dl;
  if (!has(g)) return null;
  const v = g as number;
  if (v < 70) return "low";
  if (x.glucose_type === "fasting") return v >= 126 ? "diabetic" : v >= 100 ? "borderline" : "normal";
  return v >= 200 ? "diabetic" : v >= 140 ? "borderline" : "normal";
}

// ------------------------------------------------------------------ CBAC

const TOBACCO_POINTS = { never: 0, past_or_sometimes: 1, daily: 2 } as const;

function scoreCbac(x: X): CbacResult {
  const items: Driver[] = [];
  const missing: string[] = [];
  const age = x.age;
  items.push(driver("age", age < 40 ? 0 : age < 50 ? 1 : age < 60 ? 2 : 3, age));
  if (!has(x.tobacco)) missing.push("tobacco");
  else items.push(driver("tobacco", TOBACCO_POINTS[x.tobacco!], x.tobacco));
  if (!has(x.alcohol_daily)) missing.push("alcohol_daily");
  else items.push(driver("alcohol_daily", x.alcohol_daily ? 1 : 0));
  if (!has(x.waist_cm)) missing.push("waist_cm");
  else {
    const w = x.waist_cm!;
    const pts = x.sex === "female" ? (w <= 80 ? 0 : w <= 90 ? 1 : 2) : w <= 90 ? 0 : w <= 100 ? 1 : 2;
    items.push(driver("waist", pts, w));
  }
  if (!has(x.activity)) missing.push("activity");
  else items.push(driver("inactive", x.activity === "vigorous" || x.activity === "moderate" ? 0 : 1, x.activity));
  if (!has(x.fh_diabetes) && !has(x.fh_heart_or_bp)) missing.push("family_history");
  else items.push(driver("family_history", (has(x.fh_diabetes) && x.fh_diabetes !== "none") || x.fh_heart_or_bp ? 2 : 0));
  const total = items.reduce((s, i) => s + i.points, 0);
  return { score: total, max: 10, refer: total > 4, items, missing };
}

// ------------------------------------------------------------------ diabetes

const IDRS_ACTIVITY = { vigorous: 0, moderate: 10, mild: 20, sedentary: 30 } as const;
const IDRS_FH = { none: 0, one_parent: 10, both_parents: 20 } as const;

function scoreIdrs(x: X) {
  const items: Driver[] = [];
  const imputed: string[] = [];
  const age = x.age;
  items.push(driver("age", age < 35 ? 0 : age < 50 ? 20 : 30, age));
  if (!has(x.waist_cm)) {
    imputed.push("waist_cm");
    items.push(driver("waist_unknown", 10));
  } else {
    const [a, b] = x.sex === "female" ? [80, 90] : [90, 100];
    const w = x.waist_cm!;
    items.push(driver("waist", w < a ? 0 : w < b ? 10 : 20, w));
  }
  if (!has(x.activity)) {
    imputed.push("activity");
    items.push(driver("activity_unknown", 20));
  } else items.push(driver("activity", IDRS_ACTIVITY[x.activity!], x.activity));
  if (!has(x.fh_diabetes)) {
    imputed.push("fh_diabetes");
    items.push(driver("fh_diabetes_unknown", 10));
  } else items.push(driver("fh_diabetes", IDRS_FH[x.fh_diabetes!], x.fh_diabetes));
  return { score: items.reduce((s, i) => s + i.points, 0), items, imputed };
}

function scoreDiabetes(x: X): ConditionResult {
  const idrs = scoreIdrs(x);
  let score = idrs.score;
  let band: Band = score >= 60 ? "high" : score >= 30 ? "moderate" : "low";
  const drivers = [...idrs.items];
  const sharpen: string[] = [];
  const present = DIABETES_SYMPTOMS.filter((s) => x.symptoms.includes(s));
  if (present.length >= 2) {
    band = bump(band);
    drivers.push(driver("diabetes_symptoms", 25, present.length));
  }
  const status = glucoseStatus(x);
  let action = { high: "refer_glucose_test", moderate: "lifestyle_recheck", low: "rescreen_yearly" }[band];
  if (status === "diabetic") {
    band = "high";
    score = Math.max(score, 90);
    drivers.push(driver("glucose_high", 60, x.glucose_mg_dl));
    action = "confirm_diabetes";
  } else if (status === "borderline") {
    band = bandMax(band, "moderate");
    score = Math.max(score, 50);
    drivers.push(driver("glucose_borderline", 35, x.glucose_mg_dl));
    action = band === "high" ? "refer_glucose_test" : "prediabetes_lifestyle";
  } else if (status === "normal") {
    drivers.push(driver("glucose_normal", -20, x.glucose_mg_dl, "down"));
  } else {
    sharpen.push("add_glucose");
  }
  if (x.known_diabetes) {
    band = status === "diabetic" ? "high" : "moderate";
    action = status === "diabetic" ? "known_uncontrolled" : "known_followup";
    drivers.push(driver("known_diabetes", 30));
  }
  if (idrs.imputed.includes("waist_cm")) sharpen.push("measure_waist");
  const n = idrs.imputed.length;
  const confidence =
    status === "diabetic" || status === "borderline" || status === "normal" || n === 0 ? "high" : n === 1 ? "medium" : "low";
  return {
    band,
    score: Math.min(100, score),
    drivers: topDrivers(drivers),
    action,
    confidence,
    sharpen,
    instrument: "IDRS",
    idrs: idrs.score,
  };
}

// ------------------------------------------------------------------ hypertension

export function bpStage(sbp: number, dbp: number): string {
  if (sbp >= 180 || dbp >= 110) return "severe";
  if (sbp >= 160 || dbp >= 100) return "stage2";
  if (sbp >= 140 || dbp >= 90) return "stage1";
  if (sbp >= 130 || dbp >= 85) return "high_normal";
  return "normal";
}

function htnRiskFactors(x: X): Driver[] {
  const out: Driver[] = [];
  if (x.age >= 50) out.push(driver("age", 15, x.age));
  const b = bmi(x);
  if (b !== null && b >= 25) out.push(driver("bmi", 15, b));
  else if (has(x.waist_cm) && x.waist_cm! > (x.sex === "female" ? 80 : 90)) out.push(driver("waist", 15, x.waist_cm));
  if (x.fh_heart_or_bp) out.push(driver("fh_heart_or_bp", 15));
  if (x.tobacco === "daily") out.push(driver("tobacco", 15, "daily"));
  if (x.alcohol_daily) out.push(driver("alcohol_daily", 15));
  return out;
}

function scoreHypertension(x: X): ConditionResult {
  const [sbp, dbp] = bpSummary(x);
  const factors = htnRiskFactors(x);
  const readings = validReadings(x).length;
  if (sbp === null || dbp === null) {
    return {
      band: factors.length >= 2 ? "moderate" : "low",
      score: Math.min(100, 15 * factors.length),
      drivers: topDrivers(factors),
      action: "measure_bp",
      confidence: "low",
      sharpen: ["measure_bp"],
      instrument: "NP-NCD BP thresholds",
      stage: null,
    };
  }
  const stage = bpStage(sbp, dbp);
  let band: Band = ({ severe: "high", stage2: "high", stage1: "high", high_normal: "moderate", normal: "low" } as Record<string, Band>)[stage];
  const score = round(clamp(Math.max((sbp - 100) / 80, (dbp - 60) / 50)) * 100);
  const bpPoints = ({ severe: 80, stage2: 65, stage1: 50, high_normal: 30, normal: -10 } as Record<string, number>)[stage];
  const drivers = [driver("bp", bpPoints, `${sbp}/${dbp}`, bpPoints > 0 ? "up" : "down"), ...factors];
  if (stage === "normal" && factors.length >= 3) band = "moderate";
  let action = { high: "refer_bp_confirm", moderate: "recheck_bp", low: "rescreen_yearly" }[band];
  if (x.known_hypertension) {
    action = band === "high" ? "known_uncontrolled" : "known_followup";
    drivers.push(driver("known_hypertension", 30));
  }
  const sharpen: string[] = [];
  if (readings < 2 && band !== "low") sharpen.push("repeat_bp");
  return {
    band,
    score,
    drivers: topDrivers(drivers),
    action,
    confidence: readings >= 2 ? "high" : "medium",
    sharpen,
    instrument: "NP-NCD BP thresholds",
    stage,
    sbp,
    dbp,
  };
}

// ------------------------------------------------------------------ cardiovascular (WHO 2019)

const CVD_MODERATE = 0.1;
const CVD_HIGH = 0.2;

/** WHO 2019 non-lab model, South Asia recalibration. Clinical choices documented in conditions.py. */
function scoreCvd(x: X): ConditionResult {
  const age = x.age;
  const [sbp] = bpSummary(x);
  const b = bmi(x);
  const diabetic = Boolean(x.known_diabetes) || glucoseStatus(x) === "diabetic";
  const smoker = x.tobacco === "daily" || x.tobacco === "past_or_sometimes";
  const [lo, hi] = WHO_CVD.valid_age;
  const region = WHO_CVD.default_calibration;
  const instrument = `WHO 2019 non-lab (${region
    .split("_")
    .map((w) => w[0].toUpperCase() + w.slice(1))
    .join(" ")})`;
  const sharpen: string[] = [];
  if (sbp === null) {
    return {
      band: "low", score: 0, drivers: [], action: "measure_bp", confidence: "low", sharpen: ["measure_bp"],
      instrument, computed: false, risk_10y: null, in_chart_range: age >= 40 && age <= 74,
    };
  }
  const imputedBmi = b === null;
  if (imputedBmi) sharpen.push("measure_height_weight");
  const modelAge = Math.min(Math.max(age, lo), hi);
  const bmiValue = imputedBmi ? 25 : b;
  const risk = riskFor(modelAge, x.sex, sbp, bmiValue, smoker, region);
  const band: Band = risk >= CVD_HIGH ? "high" : risk >= CVD_MODERATE ? "moderate" : "low";
  const contrib = termContributions(modelAge, x.sex, sbp, bmiValue, smoker);
  const drivers: Driver[] = [];
  const rows: [keyof typeof contrib, string, string | number | null | undefined][] = [
    ["age", "age", age],
    ["sbp", "sbp", sbp],
    ["bmi", "bmi", imputedBmi ? null : b],
    ["smoking", "tobacco", x.tobacco ?? null],
  ];
  for (const [key, code, value] of rows) {
    if (key === "bmi" && imputedBmi) continue;
    const points = Math.floor(contrib[key] * 10 + 0.5) / 10;
    drivers.push(driver(code, points, value, points > 0 ? "up" : "down"));
  }
  if (diabetic) sharpen.push("use_lab_chart");
  const confidence = imputedBmi || age < lo || age > hi || diabetic ? "low" : "high";
  return {
    band,
    score: round(Math.min(1, risk / 0.3) * 100),
    drivers: topDrivers(drivers),
    action: { high: "refer_ncd_clinic", moderate: "lifestyle_followup", low: "rescreen_yearly" }[band],
    confidence,
    sharpen,
    instrument,
    computed: true,
    risk_10y: Math.floor(risk * 10000 + 0.5) / 10000,
    in_chart_range: age >= 40 && age <= 74,
  };
}

// ------------------------------------------------------------------ anaemia

const ANAEMIA_SYMPTOM_POINTS: [string, number][] = [
  ["pallor", 3],
  ["breathless_exertion", 2],
  ["heavy_menstrual_bleeding", 2],
  ["fatigue", 1],
  ["dizziness", 1],
];

function scoreAnaemia(x: X): ConditionResult {
  const female = x.sex === "female";
  const pregnant = Boolean(x.pregnant);
  if (has(x.hb_g_dl)) {
    const hb = x.hb_g_dl!;
    const normal = pregnant ? 11 : female ? 12 : 13;
    const severe = pregnant ? 7 : 8;
    const moderate = pregnant ? 10 : 11;
    const [category, band]: [string, Band] =
      hb < severe ? ["severe", "high"] : hb < moderate ? ["moderate", "high"] : hb < normal ? ["mild", "moderate"] : ["none", "low"];
    const points = ({ severe: 80, moderate: 60, mild: 35, none: -20 } as Record<string, number>)[category];
    return {
      band,
      score: round(clamp((normal - hb) / (normal - 6)) * 100),
      drivers: [driver("hb", points, hb, points > 0 ? "up" : "down")],
      action: { high: "treat_anaemia_refer", moderate: "ifa_diet_recheck", low: "none" }[band],
      confidence: "high",
      sharpen: [],
      instrument: "WHO haemoglobin thresholds",
      category,
    };
  }
  const drivers = ANAEMIA_SYMPTOM_POINTS.filter(([s]) => x.symptoms.includes(s)).map(([s, p]) => driver(s, p));
  if (female && pregnant) drivers.push(driver("pregnant", 1));
  const total = drivers.reduce((s, d) => s + d.points, 0);
  const band: Band = total >= 4 ? "high" : total >= 2 ? "moderate" : "low";
  return {
    band,
    score: Math.min(100, total * 15),
    drivers: topDrivers(drivers),
    action: { high: "refer_hb_test", moderate: "ifa_diet_recheck", low: "none" }[band],
    confidence: "low",
    sharpen: ["add_hb"],
    instrument: "Symptom screen (confirm with Hb)",
    category: null,
  };
}

// ------------------------------------------------------------------ tuberculosis

function scoreTb(x: X): ConditionResult {
  const present = TB_CORE_SYMPTOMS.filter((s) => x.symptoms.includes(s));
  const drivers = present.map((s) => driver(s, 25));
  const blood = x.symptoms.includes("blood_in_sputum");
  const contact = x.symptoms.includes("tb_contact");
  if (blood) drivers.push(driver("blood_in_sputum", 40));
  if (contact) drivers.push(driver("tb_contact", 15));
  let band: Band = "low";
  let score = 0;
  let action = "none";
  if (present.length || blood) {
    band = "high";
    score = Math.min(100, 50 + 12.5 * present.length);
    action = "refer_sputum_test";
  } else if (contact) {
    band = "moderate";
    score = 30;
    action = "watch_tb_symptoms";
  }
  return {
    band,
    score: round(score),
    drivers: topDrivers(drivers),
    action,
    confidence: "medium",
    sharpen: [],
    instrument: "WHO four-symptom screen",
    presumptive: band === "high",
  };
}

// ------------------------------------------------------------------ red flags

function flag(code: string, level: "emergency" | "urgent"): RedFlag {
  return { code, level, action: level === "emergency" ? "call_108" : "same_day_phc" };
}

export function checkRedFlags(input: ScreeningInput): RedFlag[] {
  const x = normalize(input);
  const s = x.symptoms;
  const any = (list: string[]) => list.some((k) => s.includes(k));
  const flags: RedFlag[] = [];
  const [, , maxS, maxD] = bpSummary(x);
  if (any(STROKE_SIGNS)) flags.push(flag("stroke_signs", "emergency"));
  if (s.includes("chest_pain")) flags.push(flag("chest_pain", "emergency"));
  if (s.includes("severe_breathlessness") || (has(x.spo2) && x.spo2! < 90)) flags.push(flag("breathing", "emergency"));
  if (any(ALTERED_CONSCIOUSNESS)) flags.push(flag("altered_consciousness", "emergency"));
  if (maxS !== null && maxD !== null && (maxS >= 180 || maxD >= 110)) {
    flags.push(any(HTN_EMERGENCY_SYMPTOMS) ? flag("hypertensive_emergency", "emergency") : flag("severe_bp", "urgent"));
  }
  const g = x.glucose_mg_dl;
  if (has(g) && g! < 70) flags.push(flag("low_glucose", "emergency"));
  else if (has(g) && g! >= 400) flags.push(flag("very_high_glucose", "urgent"));
  if (has(x.hb_g_dl) && x.hb_g_dl! < 7) flags.push(flag("severe_anaemia", "urgent"));
  if (s.includes("blood_in_sputum")) flags.push(flag("haemoptysis", "urgent"));
  if (x.pregnant && any(PREGNANCY_DANGER)) flags.push(flag("pregnancy_danger", "emergency"));
  return flags;
}

// ------------------------------------------------------------------ overall

const NEEDS: Record<ConditionKey, string> = {
  diabetes: "glucose_test",
  hypertension: "bp_management",
  cvd: "ncd_clinic",
  anaemia: "hb_test",
  tb: "sputum_test",
};

function normalize(raw: ScreeningInput): X {
  const x = { ...raw, age: Math.trunc(raw.age), sex: raw.sex ?? "female" } as X;
  x.symptoms = [...new Set(raw.symptoms ?? [])].sort();
  if (x.sex !== "female") x.pregnant = false;
  return x;
}

export function score(raw: ScreeningInput): RiskResult {
  const x = normalize(raw);
  const flags = checkRedFlags(x);
  const eligible = x.age >= MIN_AGE;
  let cbac: CbacResult | null = null;
  let conditions: Partial<Record<ConditionKey, ConditionResult>> = {};
  if (eligible) {
    cbac = scoreCbac(x);
    conditions = {
      diabetes: scoreDiabetes(x),
      hypertension: scoreHypertension(x),
      cvd: scoreCvd(x),
      anaemia: scoreAnaemia(x),
      tb: scoreTb(x),
    };
  }
  const list = Object.entries(conditions) as [ConditionKey, ConditionResult][];

  let urgency: Urgency;
  if (flags.some((f) => f.level === "emergency")) urgency = "emergency";
  else if (flags.length) urgency = "urgent";
  else if (list.some(([, c]) => c.band === "high") || cbac?.refer) urgency = "soon";
  else urgency = "routine";

  const scores = list.map(([, c]) => c.score).sort((a, b) => b - a);
  let priority = 0;
  if (urgency === "emergency") priority = 100;
  else if (urgency === "urgent") priority = 90;
  else if (scores.length) {
    const top2 = scores.slice(0, 2);
    priority = round(0.7 * scores[0] + 0.3 * (top2.reduce((s, v) => s + v, 0) / top2.length)) + (x.age >= 60 ? 5 : 0);
    priority = Math.max(0, Math.min(89, priority));
  }

  let needs = [...new Set(list.filter(([, c]) => c.band === "high").map(([k]) => NEEDS[k]))].sort();
  if (urgency === "emergency") needs = ["emergency"];
  else if (urgency === "urgent" && !needs.includes("emergency")) needs = [...new Set([...needs, "same_day"])].sort();

  const reasons = [...flags.map((f) => f.code), ...list.filter(([, c]) => c.band === "high").map(([k]) => k)];
  if (cbac?.refer && !reasons.includes("cbac_above_4")) reasons.push("cbac_above_4");

  const missing = [...new Set([...(cbac?.missing ?? []), ...list.flatMap(([, c]) => c.sharpen)])].sort();
  return {
    engine_version: ENGINE_VERSION,
    eligible,
    red_flags: flags,
    emergency: urgency === "emergency",
    cbac,
    conditions,
    overall: { urgency, priority, refer: urgency !== "routine", needs, reasons },
    missing,
    // Shadow-mode ML: recorded and monitored, never used for the band, urgency or referral above.
    model: eligible ? modelPredict(x, bpSummary, bmi) : null,
  };
}
